/**
 * 표지 URL 을 미리 구운 WebP 로 바꾼다. 아직 안 구운 새 편은 원본을 돌려주므로
 * 화면이 깨지지는 않는다(대신 그 한 장은 원본 크기를 그대로 받는다).
 */
export function coverThumb(url: string | null | undefined, size: CoverSize): string | null {
  if (!url) return null;
  return COVER_THUMBS[url]?.[size] ?? url;
}
